import { spawnSync } from 'node:child_process';
import { randomBytes } from 'node:crypto';
import { existsSync, mkdirSync, mkdtempSync, readFileSync, readdirSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join, resolve } from 'node:path';

/**
 * The prior-line upgrade fixture: a production app generated by the LAST
 * PUBLISHED CLI and core (0.1.1 / 0.10.1), moved onto the archives under
 * test with the two commands MIGRATING.md names.
 *
 *   node scripts/upgrade-smoke.mjs <new-artifacts> [old cli version] [old core version]
 *
 * Proves, without services: the unmigrated app is refused by the new core
 * with the 0.11 diagnostics (the legacy variables file, the config factory)
 * before any connection; `tulipes migrate 0.11` then `tulipes config:import`
 * leave an app that installs, syncs, typechecks, describes itself offline
 * on plain node and boots far enough to reach its database provider — with
 * the values its env file held now in the settings store.
 */
const [artifactPath, oldCli = '0.1.1', oldCore = '0.10.1'] = process.argv.slice(2);
if (!artifactPath) throw new Error('Usage: upgrade-smoke.mjs <artifacts> [old cli version] [old core version]');
const artifacts = resolve(artifactPath);
const workspace = mkdtempSync(join(tmpdir(), 'tulipes-upgrade-'));
const scripts = import.meta.dirname;
const logs = resolve('reports', 'upgrade-smoke');
mkdirSync(logs, { recursive: true });
let step = 0;
function run(command, args, cwd, env = process.env, { expectFailure } = {}) {
  const result = spawnSync(command, args, { cwd, env, encoding: 'utf8', timeout: 180_000 });
  const file = join(logs, `${String(++step).padStart(2, '0')}-${command.split('/').at(-1)}.log`);
  const output = (result.stdout ?? '') + (result.stderr ?? '');
  writeFileSync(file, `$ ${command} ${args.join(' ')}\n\n` + output);
  const failed = result.status !== 0;
  if (failed !== Boolean(expectFailure)) throw new Error(`${command} ${args.join(' ')} ${failed ? 'failed' : 'unexpectedly succeeded'}; see ${file}\n${result.error ?? ''}\n${result.stderr ?? ''}`);
  return output;
}
const install = (cwd, env = process.env) => run('pnpm', ['install', '--no-frozen-lockfile'], cwd, env);
const readJson = file => JSON.parse(readFileSync(file, 'utf8'));
const writeJson = (file, value) => writeFileSync(file, JSON.stringify(value, null, 2) + '\n');

try {
  run(process.execPath, [join(scripts, 'artifacts.mjs'), 'verify', artifacts], workspace);
  const manifest = readJson(join(artifacts, 'manifest.json'));
  const resolutions = Object.fromEntries(manifest.packages.map(pkg => [pkg.name, 'file:' + join(artifacts, pkg.file)]));

  // 1. The old world: the last published CLI generates a production app.
  const oldRoot = join(workspace, 'old-cli');
  mkdirSync(oldRoot);
  writeJson(join(oldRoot, 'package.json'), { private: true, packageManager: 'pnpm@10.28.0', dependencies: { '@tulipes/cli': oldCli, '@tulipes/core': oldCore } });
  install(oldRoot);
  const generatedBy = readJson(join(oldRoot, 'node_modules/@tulipes/core/package.json')).version;
  const app = join(workspace, 'app');
  run(process.execPath, [join(oldRoot, 'node_modules/@tulipes/cli/dist/bin.js'), 'init', app, '--preset', 'production'], workspace);
  const pkgFile = join(app, 'package.json');
  if (!existsSync(join(app, 'modules/users/meta.variables.json'))) throw new Error('The old starter does not use the 0.10 contract this fixture upgrades from');
  const oldVariables = ['USERS_MAX_SESSIONS=3', 'USERS_SIGNUP_MODE=invite', 'HELLO_GREETING=Carried'];
  writeFileSync(join(app, '.envs/.env.production'), readFileSync(join(app, '.envs/.env.production'), 'utf8') + '\n' + oldVariables.join('\n') + '\n');

  // 2. The new archives installed under the old app, converted to pnpm, nothing else changed.
  const before = readJson(pkgFile);
  const { workspaces, resolutions: yarnResolutions, ...rest } = before;
  writeJson(pkgFile, { ...rest, packageManager: 'pnpm@10.28.0', pnpm: { overrides: { ...(yarnResolutions && { 'pm2>js-yaml': yarnResolutions['pm2/js-yaml'] }), ...resolutions }, onlyBuiltDependencies: ['esbuild', 'msgpackr-extract'] } });
  writeFileSync(join(app, 'pnpm-workspace.yaml'), 'packages:\n' + (workspaces ?? ['modules/*']).map(glob => `  - ${glob}\n`).join(''));
  rmSync(join(app, '.yarnrc.yml'), { force: true });
  const env = { ...process.env, APP_ENV: 'production', LOG_FILE: 'false', LOG_CONSOLE: 'false', PORT: '0',
    MONGO_URI: 'mongodb://127.0.0.1:1/unreachable', REDIS_URL: 'redis://127.0.0.1:1',
    JWT_ACCESS_SECRET: randomBytes(32).toString('hex'), JWT_REFRESH_SECRET: randomBytes(32).toString('hex'),
    AUTH_ADMIN_EMAIL: 'upgrade@example.test', AUTH_ADMIN_PASSWORD: randomBytes(32).toString('hex') };
  install(app, env);
  const newBin = join(app, 'node_modules/@tulipes/cli/dist/bin.js');
  const guard = join(app, 'offline-guard.mjs');
  writeFileSync(guard, `import { Socket } from 'node:net';\nSocket.prototype.connect = function () { throw new Error('a connection was attempted'); };\n`);
  writeFileSync(join(app, 'try-boot.mjs'), `
    import { boot } from '@tulipes/core/boot';
    try { const handle = await boot({ rootDir: import.meta.dirname, mode: 'script', handleSignals: false }); await handle.shutdown(); }
    catch (error) { console.error(error.message); process.exit(3); }
  `);
  // The old app still runs through tsx (its own devDependency) until migrated.
  const tryBoot = (loader) => run(process.execPath, ['--import', guard, ...(loader ? ['--import', 'tsx'] : []), 'try-boot.mjs'], app, env, { expectFailure: true });

  // 2a. Unmigrated: refused by the environment phase, naming the legacy file, never connecting.
  let output = tryBoot(true);
  if (!output.includes('meta.variables.json')) throw new Error(`Unmigrated app was not told about meta.variables.json\n${output}`);
  if (output.includes('a connection was attempted')) throw new Error('Unmigrated app attempted a connection');

  // 3. The two commands.
  output = run(process.execPath, [newBin, 'migrate', '0.11'], app, env);
  if (!/migrated \d+ thing\(s\)/.test(output)) throw new Error('migrate reported nothing\n' + output);
  const record = readJson(join(app, 'config/migration-0.11.json'));
  for (const [namespace, field] of [['users', 'maxSessions'], ['users', 'signupMode'], ['hello', 'greeting']]) {
    if (!record.settings[namespace]?.[field]) throw new Error(`migration did not record ${namespace}.${field}`);
  }
  if (existsSync(join(app, 'modules/users/meta.variables.json')) || existsSync(join(app, 'modules/users/schemas.ts')) || !existsSync(join(app, 'modules/auth/lib/index.ts'))) throw new Error('migrate did not move the module files');
  if (readJson(pkgFile).devDependencies?.tsx) throw new Error('migrate left tsx in the manifest');
  install(app, env);
  output = run(process.execPath, [newBin, 'config:import', '--env', 'production'], app, env);
  if (!/users: maxSessions ← USERS_MAX_SESSIONS, signupMode ← USERS_SIGNUP_MODE/.test(output) || !/hello: greeting ← HELLO_GREETING/.test(output)) throw new Error('config:import did not carry the values\n' + output);
  const stored = readJson(join(app, 'config/settings.production.json'));
  if (stored.users?.values?.maxSessions !== 3 || stored.users?.values?.signupMode !== 'invite' || stored.hello?.values?.greeting !== 'Carried') throw new Error('the store does not hold the imported values: ' + JSON.stringify(stored));

  // 4. The migrated app, on plain node: syncs, typechecks, describes itself offline, boots to its provider.
  for (const script of ['sync', 'typecheck']) run('pnpm', [script], app, env);
  if (run('pnpm', ['ls', 'tsx', '--depth', '0'], app, env).includes('tsx@')) throw new Error('tsx is still installed in the migrated app');
  run(process.execPath, ['--import', guard, newBin, 'routes'], app, env);
  run(process.execPath, ['--import', guard, newBin, 'spec', '--openapi', 'docs/openapi.json', '--postman', 'docs/collection.json'], app, env);
  const spec = readJson(join(app, 'docs/openapi.json'));
  if (!spec.paths['/api/v1/auth/login']) throw new Error('Migrated app lost its routes');
  output = tryBoot(false);
  if (output.includes('meta.variables.json') || output.includes('module.config')) throw new Error('Migrated app still gets migration diagnostics\n' + output);
  if (!/Boot aborted during "providers"/.test(output) || !/database connection failed/.test(output)) throw new Error('Migrated app did not reach the Mongoose provider\n' + output);
  // What config:import wrote is what the app would boot with: the store is read before the provider is.
  writeFileSync(join(app, 'read-settings.mjs'), `
    import { FileSettingsStore } from '@tulipes/core/config';
    const store = new FileSettingsStore(import.meta.dirname, 'production');
    console.log(JSON.stringify({ users: (await store.load('users'))?.values, hello: (await store.load('hello'))?.values }));
  `);
  const values = JSON.parse(run(process.execPath, ['read-settings.mjs'], app, env).trim().split('\n').at(-1));
  if (values.users?.maxSessions !== 3 || values.hello?.greeting !== 'Carried') throw new Error('the migrated app does not read the imported values: ' + JSON.stringify(values));

  writeJson(join(logs, 'summary.json'), { generatedBy, oldCli, upgradedTo: Object.fromEntries(manifest.packages.map(pkg => [pkg.name, pkg.version])), imported: values });
  console.log(`upgrade: production app generated by cli ${oldCli} / core ${generatedBy} was refused with the 0.11 diagnostics, then migrated with \`tulipes migrate 0.11\` and \`tulipes config:import\`, installed without tsx, typechecked, described itself offline on node and boots to its provider with its previous settings on ${manifest.packages.map(pkg => `${pkg.name}@${pkg.version}`).join(', ')}`);
} finally {
  rmSync(workspace, { recursive: true, force: true });
}
